INSERT INTO `oc_information_description` (`information_id`, `language_id`, `title`, `description`, `meta_title`, `meta_description`, `meta_keyword`) VALUES (1, 2, 'Giới thiệu về HanMartket', '&lt;h2 data-end=&quot;2012&quot; data-start=&quot;1985&quot;&gt;&lt;strong data-end=&quot;2012&quot; data-start=&quot;1988&quot;&gt;GIỚI THIỆU HANMARKET&lt;/strong&gt;&lt;/h2&gt;\r\n\r\n&lt;p data-end=&quot;2216&quot; data-start=&quot;2014&quot;&gt;&lt;strong data-end=&quot;2027&quot; data-start=&quot;2014&quot;&gt;HanMarket&lt;/strong&gt; được xây dựng nhằm hỗ trợ các &lt;strong data-end=&quot;2122&quot; data-start=&quot;2058&quot;&gt;hộ kinh doanh và ki-ốt bán hàng lưu niệm tại Chợ Hàn Đà Nẵng&lt;/strong&gt; trong việc quản lý hoạt động kinh doanh một cách &lt;strong data-end=&quot;2215&quot; data-start=&quot;2172&quot;&gt;đơn giản – dễ sử dụng – phù hợp thực tế&lt;/strong&gt;.&lt;/p&gt;\r\n\r\n&lt;hr data-end=&quot;2221&quot; data-start=&quot;2218&quot; /&gt;\r\n&lt;h3 data-end=&quot;2238&quot; data-start=&quot;2223&quot;&gt;🎯 Mục tiêu&lt;/h3&gt;\r\n\r\n&lt;ul data-end=&quot;2398&quot; data-start=&quot;2240&quot;&gt;\r\n	&lt;li data-end=&quot;2283&quot; data-start=&quot;2240&quot;&gt;\r\n	&lt;p data-end=&quot;2283&quot; data-start=&quot;2242&quot;&gt;Giúp tiểu thương quản lý bán hàng dễ dàng&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;2321&quot; data-start=&quot;2284&quot;&gt;\r\n	&lt;p data-end=&quot;2321&quot; data-start=&quot;2286&quot;&gt;Giảm sai sót trong ghi chép sổ sách&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;2359&quot; data-start=&quot;2322&quot;&gt;\r\n	&lt;p data-end=&quot;2359&quot; data-start=&quot;2324&quot;&gt;Theo dõi doanh thu, tồn kho rõ ràng&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;2398&quot; data-start=&quot;2360&quot;&gt;\r\n	&lt;p data-end=&quot;2398&quot; data-start=&quot;2362&quot;&gt;Hỗ trợ dữ liệu phục vụ khai báo thuế&lt;/p&gt;\r\n	&lt;/li&gt;\r\n&lt;/ul&gt;\r\n\r\n&lt;hr data-end=&quot;2403&quot; data-start=&quot;2400&quot; /&gt;\r\n&lt;h3 data-end=&quot;2428&quot; data-start=&quot;2405&quot;&gt;💡 Giá trị mang lại&lt;/h3&gt;\r\n\r\n&lt;ul data-end=&quot;2575&quot; data-start=&quot;2430&quot;&gt;\r\n	&lt;li data-end=&quot;2459&quot; data-start=&quot;2430&quot;&gt;\r\n	&lt;p data-end=&quot;2459&quot; data-start=&quot;2432&quot;&gt;Giao diện đơn giản, dễ dùng&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;2500&quot; data-start=&quot;2460&quot;&gt;\r\n	&lt;p data-end=&quot;2500&quot; data-start=&quot;2462&quot;&gt;Phù hợp với người ít sử dụng công nghệ&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;2529&quot; data-start=&quot;2501&quot;&gt;\r\n	&lt;p data-end=&quot;2529&quot; data-start=&quot;2503&quot;&gt;Dữ liệu rõ ràng, minh bạch&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;2575&quot; data-start=&quot;2530&quot;&gt;\r\n	&lt;p data-end=&quot;2575&quot; data-start=&quot;2532&quot;&gt;Phục vụ đúng nhu cầu kinh doanh tại Chợ Hàn&lt;/p&gt;\r\n	&lt;/li&gt;\r\n&lt;/ul&gt;\r\n\r\n&lt;hr data-end=&quot;2580&quot; data-start=&quot;2577&quot; /&gt;\r\n&lt;h3 data-end=&quot;2606&quot; data-start=&quot;2582&quot;&gt;🏪 Đối tượng sử dụng&lt;/h3&gt;\r\n\r\n&lt;ul data-end=&quot;2691&quot; data-start=&quot;2608&quot;&gt;\r\n	&lt;li data-end=&quot;2630&quot; data-start=&quot;2608&quot;&gt;\r\n	&lt;p data-end=&quot;2630&quot; data-start=&quot;2610&quot;&gt;Hộ kinh doanh cá thể&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;2656&quot; data-start=&quot;2631&quot;&gt;\r\n	&lt;p data-end=&quot;2656&quot; data-start=&quot;2633&quot;&gt;Ki-ốt bán hàng lưu niệm&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;2691&quot; data-start=&quot;2657&quot;&gt;\r\n	&lt;p data-end=&quot;2691&quot; data-start=&quot;2659&quot;&gt;Cửa hàng nhỏ tại Chợ Hàn Đà Nẵng&lt;/p&gt;\r\n	&lt;/li&gt;\r\n&lt;/ul&gt;\r\n\r\n&lt;hr data-end=&quot;2696&quot; data-start=&quot;2693&quot; /&gt;\r\n&lt;h3 data-end=&quot;2712&quot; data-start=&quot;2698&quot;&gt;🤝 Cam kết&lt;/h3&gt;\r\n\r\n&lt;p data-end=&quot;2732&quot; data-start=&quot;2714&quot;&gt;HanMarket cam kết:&lt;/p&gt;\r\n\r\n&lt;ul data-end=&quot;2838&quot; data-start=&quot;2733&quot;&gt;\r\n	&lt;li data-end=&quot;2763&quot; data-start=&quot;2733&quot;&gt;\r\n	&lt;p data-end=&quot;2763&quot; data-start=&quot;2735&quot;&gt;Không bán dữ liệu người dùng&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;2794&quot; data-start=&quot;2764&quot;&gt;\r\n	&lt;p data-end=&quot;2794&quot; data-start=&quot;2766&quot;&gt;Bảo mật thông tin kinh doanh&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;2838&quot; data-start=&quot;2795&quot;&gt;\r\n	&lt;p data-end=&quot;2838&quot; data-start=&quot;2797&quot;&gt;Hỗ trợ người dùng trong quá trình sử dụng&lt;/p&gt;\r\n	&lt;/li&gt;\r\n&lt;/ul&gt;', 'Giới thiệu', 'HanMarket được xây dựng nhằm hỗ trợ các hộ kinh doanh và ki-ốt bán hàng lưu niệm tại Chợ Hàn Đà Nẵng trong việc quản lý hoạt động kinh doanh một cách đơn giản – dễ sử dụng – phù hợp thực tế.', 'Giới thiệu');
INSERT INTO `oc_information_description` (`information_id`, `language_id`, `title`, `description`, `meta_title`, `meta_description`, `meta_keyword`) VALUES (2, 1, 'Terms &amp; Conditions', '&lt;p&gt;Terms &amp;amp; Conditions&lt;/p&gt;', 'Terms &amp; Conditions', '', '');
INSERT INTO `oc_information_description` (`information_id`, `language_id`, `title`, `description`, `meta_title`, `meta_description`, `meta_keyword`) VALUES (2, 2, 'Điều khoản sử dụng', '&lt;h2 data-end=&quot;334&quot; data-start=&quot;309&quot;&gt;&lt;strong data-end=&quot;334&quot; data-start=&quot;312&quot;&gt;ĐIỀU KHOẢN SỬ DỤNG&lt;/strong&gt;&lt;/h2&gt;\r\n\r\n&lt;p data-end=&quot;544&quot; data-start=&quot;373&quot;&gt;Khi truy cập và sử dụng website &lt;strong data-end=&quot;418&quot; data-start=&quot;405&quot;&gt;HanMarket&lt;/strong&gt;, bạn đồng ý tuân thủ các điều khoản dưới đây. Nếu bạn không đồng ý với bất kỳ điều khoản nào, vui lòng ngừng sử dụng dịch vụ.&lt;/p&gt;\r\n\r\n&lt;h3 data-end=&quot;576&quot; data-start=&quot;551&quot;&gt;1. Giới thiệu dịch vụ&lt;/h3&gt;\r\n\r\n&lt;p data-end=&quot;607&quot; data-start=&quot;578&quot;&gt;HanMarket là nền tảng hỗ trợ:&lt;/p&gt;\r\n\r\n&lt;ul data-end=&quot;806&quot; data-start=&quot;608&quot;&gt;\r\n	&lt;li data-end=&quot;626&quot; data-start=&quot;608&quot;&gt;\r\n	&lt;p data-end=&quot;626&quot; data-start=&quot;610&quot;&gt;Quản lý bán hàng&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;664&quot; data-start=&quot;627&quot;&gt;\r\n	&lt;p data-end=&quot;664&quot; data-start=&quot;629&quot;&gt;Quản lý đơn nhập hàng, đơn bán hàng&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;683&quot; data-start=&quot;665&quot;&gt;\r\n	&lt;p data-end=&quot;683&quot; data-start=&quot;667&quot;&gt;Theo dõi tồn kho&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;722&quot; data-start=&quot;684&quot;&gt;\r\n	&lt;p data-end=&quot;722&quot; data-start=&quot;686&quot;&gt;Quản lý thông tin hóa đơn, doanh thu&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;806&quot; data-start=&quot;723&quot;&gt;\r\n	&lt;p data-end=&quot;806&quot; data-start=&quot;725&quot;&gt;Hỗ trợ dữ liệu phục vụ khai báo thuế cho hộ kinh doanh, ki-ốt tại Chợ Hàn Đà Nẵng&lt;/p&gt;\r\n	&lt;/li&gt;\r\n&lt;/ul&gt;\r\n\r\n&lt;hr data-end=&quot;811&quot; data-start=&quot;808&quot; /&gt;\r\n&lt;h3 data-end=&quot;840&quot; data-start=&quot;813&quot;&gt;2. Tài khoản người dùng&lt;/h3&gt;\r\n\r\n&lt;ul data-end=&quot;1029&quot; data-start=&quot;842&quot;&gt;\r\n	&lt;li data-end=&quot;899&quot; data-start=&quot;842&quot;&gt;\r\n	&lt;p data-end=&quot;899&quot; data-start=&quot;844&quot;&gt;Người dùng chịu trách nhiệm bảo mật thông tin đăng nhập&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;948&quot; data-start=&quot;900&quot;&gt;\r\n	&lt;p data-end=&quot;948&quot; data-start=&quot;902&quot;&gt;Không chia sẻ tài khoản cho người khác sử dụng&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;1029&quot; data-start=&quot;949&quot;&gt;\r\n	&lt;p data-end=&quot;1029&quot; data-start=&quot;951&quot;&gt;Mọi hoạt động phát sinh từ tài khoản được xem là do chính người dùng thực hiện&lt;/p&gt;\r\n	&lt;/li&gt;\r\n&lt;/ul&gt;\r\n\r\n&lt;hr data-end=&quot;1034&quot; data-start=&quot;1031&quot; /&gt;\r\n&lt;h3 data-end=&quot;1069&quot; data-start=&quot;1036&quot;&gt;3. Trách nhiệm của người dùng&lt;/h3&gt;\r\n\r\n&lt;p data-end=&quot;1090&quot; data-start=&quot;1071&quot;&gt;Người dùng cam kết:&lt;/p&gt;\r\n\r\n&lt;ul data-end=&quot;1262&quot; data-start=&quot;1091&quot;&gt;\r\n	&lt;li data-end=&quot;1133&quot; data-start=&quot;1091&quot;&gt;\r\n	&lt;p data-end=&quot;1133&quot; data-start=&quot;1093&quot;&gt;Cung cấp thông tin chính xác khi đăng ký&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;1186&quot; data-start=&quot;1134&quot;&gt;\r\n	&lt;p data-end=&quot;1186&quot; data-start=&quot;1136&quot;&gt;Sử dụng hệ thống đúng mục đích kinh doanh hợp pháp&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;1262&quot; data-start=&quot;1187&quot;&gt;\r\n	&lt;p data-end=&quot;1262&quot; data-start=&quot;1189&quot;&gt;Tự chịu trách nhiệm về tính chính xác của dữ liệu bán hàng, hóa đơn, thuế&lt;/p&gt;\r\n	&lt;/li&gt;\r\n&lt;/ul&gt;\r\n\r\n&lt;hr data-end=&quot;1267&quot; data-start=&quot;1264&quot; /&gt;\r\n&lt;h3 data-end=&quot;1296&quot; data-start=&quot;1269&quot;&gt;4. Giới hạn trách nhiệm&lt;/h3&gt;\r\n\r\n&lt;p data-end=&quot;1308&quot; data-start=&quot;1298&quot;&gt;HanMarket:&lt;/p&gt;\r\n\r\n&lt;ul data-end=&quot;1524&quot; data-start=&quot;1309&quot;&gt;\r\n	&lt;li data-end=&quot;1372&quot; data-start=&quot;1309&quot;&gt;\r\n	&lt;p data-end=&quot;1372&quot; data-start=&quot;1311&quot;&gt;Không chịu trách nhiệm cho sai sót dữ liệu do người dùng nhập&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;1428&quot; data-start=&quot;1373&quot;&gt;\r\n	&lt;p data-end=&quot;1428&quot; data-start=&quot;1375&quot;&gt;Không đại diện cho cơ quan thuế hoặc cơ quan nhà nước&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;1524&quot; data-start=&quot;1429&quot;&gt;\r\n	&lt;p data-end=&quot;1524&quot; data-start=&quot;1431&quot;&gt;Không chịu trách nhiệm cho các quyết định kinh doanh của người dùng dựa trên dữ liệu hệ thống&lt;/p&gt;\r\n	&lt;/li&gt;\r\n&lt;/ul&gt;\r\n\r\n&lt;hr data-end=&quot;1529&quot; data-start=&quot;1526&quot; /&gt;\r\n&lt;h3 data-end=&quot;1569&quot; data-start=&quot;1531&quot;&gt;5. Tạm ngưng hoặc chấm dứt dịch vụ&lt;/h3&gt;\r\n\r\n&lt;p data-end=&quot;1590&quot; data-start=&quot;1571&quot;&gt;Chúng tôi có quyền:&lt;/p&gt;\r\n\r\n&lt;ul data-end=&quot;1704&quot; data-start=&quot;1591&quot;&gt;\r\n	&lt;li data-end=&quot;1645&quot; data-start=&quot;1591&quot;&gt;\r\n	&lt;p data-end=&quot;1645&quot; data-start=&quot;1593&quot;&gt;Tạm ngưng tài khoản khi phát hiện vi phạm điều khoản&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;1704&quot; data-start=&quot;1646&quot;&gt;\r\n	&lt;p data-end=&quot;1704&quot; data-start=&quot;1648&quot;&gt;Chấm dứt dịch vụ nếu có yêu cầu từ cơ quan có thẩm quyền&lt;/p&gt;\r\n	&lt;/li&gt;\r\n&lt;/ul&gt;\r\n\r\n&lt;hr data-end=&quot;1709&quot; data-start=&quot;1706&quot; /&gt;\r\n&lt;h3 data-end=&quot;1737&quot; data-start=&quot;1711&quot;&gt;6. Thay đổi điều khoản&lt;/h3&gt;\r\n\r\n&lt;p data-end=&quot;1828&quot; data-start=&quot;1739&quot;&gt;Điều khoản sử dụng có thể được cập nhật theo thời gian và sẽ được thông báo trên website.&lt;/p&gt;\r\n\r\n&lt;hr data-end=&quot;1833&quot; data-start=&quot;1830&quot; /&gt;\r\n&lt;h3 data-end=&quot;1859&quot; data-start=&quot;1835&quot;&gt;7. Thông tin liên hệ&lt;/h3&gt;\r\n\r\n&lt;p data-end=&quot;1919&quot; data-start=&quot;1861&quot;&gt;HanMarket – Chợ Hàn Đà Nẵng&lt;br data-end=&quot;1891&quot; data-start=&quot;1888&quot; /&gt;\r\nEmail / SĐT: &lt;i&gt;0867687772&lt;/i&gt;&lt;/p&gt;', 'Terms of Service – Điều khoản sử dụng', 'Khi truy cập và sử dụng website HanMarket, bạn đồng ý tuân thủ các điều khoản dưới đây. Nếu bạn không đồng ý với bất kỳ điều khoản nào, vui lòng ngừng sử dụng dịch vụ.', 'Terms of Service – Điều khoản sử dụng');
INSERT INTO `oc_information_description` (`information_id`, `language_id`, `title`, `description`, `meta_title`, `meta_description`, `meta_keyword`) VALUES (3, 1, 'CHÍNH SÁCH BẢO MẬT', '&lt;h1 data-end=&quot;1193&quot; data-start=&quot;1169&quot;&gt;&lt;strong data-end=&quot;1193&quot; data-start=&quot;1171&quot;&gt;CHÍNH SÁCH BẢO MẬT&lt;/strong&gt;&lt;/h1&gt;\r\n\r\n&lt;p data-end=&quot;1362&quot; data-start=&quot;1232&quot;&gt;HanMarket cam kết bảo vệ thông tin cá nhân của người dùng khi sử dụng website và các dịch vụ quản lý bán hàng tại Chợ Hàn Đà Nẵng.&lt;/p&gt;\r\n\r\n&lt;h2 data-end=&quot;1403&quot; data-start=&quot;1369&quot;&gt;1. Thông tin chúng tôi thu thập&lt;/h2&gt;\r\n\r\n&lt;p data-end=&quot;1449&quot; data-start=&quot;1405&quot;&gt;Chúng tôi có thể thu thập các thông tin sau:&lt;/p&gt;\r\n\r\n&lt;ul data-end=&quot;1747&quot; data-start=&quot;1451&quot;&gt;\r\n	&lt;li data-end=&quot;1499&quot; data-start=&quot;1451&quot;&gt;\r\n	&lt;p data-end=&quot;1499&quot; data-start=&quot;1453&quot;&gt;Thông tin tài khoản: tên, số điện thoại, email&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;1565&quot; data-start=&quot;1500&quot;&gt;\r\n	&lt;p data-end=&quot;1565&quot; data-start=&quot;1502&quot;&gt;Thông tin ki-ốt/hộ kinh doanh: tên cửa hàng, địa chỉ kinh doanh&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;1630&quot; data-start=&quot;1566&quot;&gt;\r\n	&lt;p data-end=&quot;1630&quot; data-start=&quot;1568&quot;&gt;Dữ liệu bán hàng: đơn hàng, đơn nhập hàng, sản phẩm, doanh thu&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;1684&quot; data-start=&quot;1631&quot;&gt;\r\n	&lt;p data-end=&quot;1684&quot; data-start=&quot;1633&quot;&gt;Thông tin hóa đơn, thuế phục vụ việc quản lý nội bộ&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;1747&quot; data-start=&quot;1685&quot;&gt;\r\n	&lt;p data-end=&quot;1747&quot; data-start=&quot;1687&quot;&gt;Dữ liệu kỹ thuật: địa chỉ IP, trình duyệt, thiết bị truy cập&lt;/p&gt;\r\n	&lt;/li&gt;\r\n&lt;/ul&gt;\r\n\r\n&lt;h2 data-end=&quot;1786&quot; data-start=&quot;1754&quot;&gt;2. Mục đích sử dụng thông tin&lt;/h2&gt;\r\n\r\n&lt;p data-end=&quot;1823&quot; data-start=&quot;1788&quot;&gt;Thông tin thu thập được sử dụng để:&lt;/p&gt;\r\n\r\n&lt;ul data-end=&quot;2082&quot; data-start=&quot;1825&quot;&gt;\r\n	&lt;li data-end=&quot;1873&quot; data-start=&quot;1825&quot;&gt;\r\n	&lt;p data-end=&quot;1873&quot; data-start=&quot;1827&quot;&gt;Cung cấp và vận hành hệ thống quản lý bán hàng&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;1924&quot; data-start=&quot;1874&quot;&gt;\r\n	&lt;p data-end=&quot;1924&quot; data-start=&quot;1876&quot;&gt;Quản lý đơn hàng, tồn kho, nhập hàng và bán hàng&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;1985&quot; data-start=&quot;1925&quot;&gt;\r\n	&lt;p data-end=&quot;1985&quot; data-start=&quot;1927&quot;&gt;Hỗ trợ theo dõi doanh thu và dữ liệu phục vụ khai báo thuế&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;2042&quot; data-start=&quot;1986&quot;&gt;\r\n	&lt;p data-end=&quot;2042&quot; data-start=&quot;1988&quot;&gt;Cải thiện chất lượng dịch vụ và trải nghiệm người dùng&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;2082&quot; data-start=&quot;2043&quot;&gt;\r\n	&lt;p data-end=&quot;2082&quot; data-start=&quot;2045&quot;&gt;Liên hệ hỗ trợ kỹ thuật khi cần thiết&lt;/p&gt;\r\n	&lt;/li&gt;\r\n&lt;/ul&gt;\r\n\r\n&lt;h2 data-end=&quot;2110&quot; data-start=&quot;2089&quot;&gt;3. Bảo mật dữ liệu&lt;/h2&gt;\r\n\r\n&lt;ul data-end=&quot;2345&quot; data-start=&quot;2112&quot;&gt;\r\n	&lt;li data-end=&quot;2188&quot; data-start=&quot;2112&quot;&gt;\r\n	&lt;p data-end=&quot;2188&quot; data-start=&quot;2114&quot;&gt;Dữ liệu người dùng được lưu trữ trên hệ thống có biện pháp bảo mật phù hợp&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;2235&quot; data-start=&quot;2189&quot;&gt;\r\n	&lt;p data-end=&quot;2235&quot; data-start=&quot;2191&quot;&gt;Chỉ người có quyền mới được truy cập dữ liệu&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;2345&quot; data-start=&quot;2236&quot;&gt;\r\n	&lt;p data-end=&quot;2345&quot; data-start=&quot;2238&quot;&gt;Không chia sẻ dữ liệu cho bên thứ ba khi chưa có sự đồng ý của người dùng, trừ trường hợp pháp luật yêu cầu&lt;/p&gt;\r\n	&lt;/li&gt;\r\n&lt;/ul&gt;\r\n\r\n&lt;h2 data-end=&quot;2390&quot; data-start=&quot;2352&quot;&gt;4. Chia sẻ thông tin với bên thứ ba&lt;/h2&gt;\r\n\r\n&lt;p data-end=&quot;2498&quot; data-start=&quot;2392&quot;&gt;HanMarket &lt;strong data-end=&quot;2456&quot; data-start=&quot;2402&quot;&gt;không bán, trao đổi hoặc chia sẻ thông tin cá nhân&lt;/strong&gt; của người dùng cho bên thứ ba, ngoại trừ:&lt;/p&gt;\r\n\r\n&lt;ul data-end=&quot;2624&quot; data-start=&quot;2500&quot;&gt;\r\n	&lt;li data-end=&quot;2550&quot; data-start=&quot;2500&quot;&gt;\r\n	&lt;p data-end=&quot;2550&quot; data-start=&quot;2502&quot;&gt;Khi có yêu cầu từ cơ quan nhà nước có thẩm quyền&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;2624&quot; data-start=&quot;2551&quot;&gt;\r\n	&lt;p data-end=&quot;2624&quot; data-start=&quot;2553&quot;&gt;Khi cần thiết để bảo trì, vận hành hệ thống (đối tác kỹ thuật, máy chủ)&lt;/p&gt;\r\n	&lt;/li&gt;\r\n&lt;/ul&gt;\r\n\r\n&lt;h2 data-end=&quot;2657&quot; data-start=&quot;2631&quot;&gt;5. Quyền của người dùng&lt;/h2&gt;\r\n\r\n&lt;p data-end=&quot;2679&quot; data-start=&quot;2659&quot;&gt;Người dùng có quyền:&lt;/p&gt;\r\n\r\n&lt;ul data-end=&quot;2819&quot; data-start=&quot;2681&quot;&gt;\r\n	&lt;li data-end=&quot;2729&quot; data-start=&quot;2681&quot;&gt;\r\n	&lt;p data-end=&quot;2729&quot; data-start=&quot;2683&quot;&gt;Xem, chỉnh sửa hoặc cập nhật thông tin cá nhân&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;2774&quot; data-start=&quot;2730&quot;&gt;\r\n	&lt;p data-end=&quot;2774&quot; data-start=&quot;2732&quot;&gt;Yêu cầu xóa tài khoản và dữ liệu liên quan&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;2819&quot; data-start=&quot;2775&quot;&gt;\r\n	&lt;p data-end=&quot;2819&quot; data-start=&qu