INSERT INTO `oc_information_description` (`information_id`, `language_id`, `title`, `description`, `meta_title`, `meta_description`, `meta_keyword`) VALUES (6, 2, 'Chính sách đổi trả và hoàn tiền', '&lt;h2 data-end=&quot;449&quot; data-start=&quot;412&quot;&gt;&lt;strong data-end=&quot;449&quot; data-start=&quot;415&quot;&gt;CHÍNH SÁCH ĐỔI TRẢ &amp;amp; HOÀN TIỀN&lt;/strong&gt;&lt;/h2&gt;\r\n\r\n&lt;p data-end=&quot;566&quot; data-start=&quot;451&quot;&gt;HanMarket mong muốn mang lại trải nghiệm mua sắm tốt nhất cho khách hàng khi mua hàng lưu niệm tại Chợ Hàn Đà Nẵng.&lt;/p&gt;\r\n\r\n&lt;hr data-end=&quot;571&quot; data-start=&quot;568&quot; /&gt;\r\n&lt;h3 data-end=&quot;597&quot; data-start=&quot;573&quot;&gt;1. Điều kiện đổi trả&lt;/h3&gt;\r\n\r\n&lt;p data-end=&quot;664&quot; data-start=&quot;599&quot;&gt;Khách hàng có thể yêu cầu đổi hoặc trả hàng trong các trường hợp:&lt;/p&gt;\r\n\r\n&lt;ul data-end=&quot;779&quot; data-start=&quot;666&quot;&gt;\r\n	&lt;li data-end=&quot;706&quot; data-start=&quot;666&quot;&gt;\r\n	&lt;p data-end=&quot;706&quot; data-start=&quot;668&quot;&gt;Sản phẩm bị lỗi, hư hỏng do vận chuyển&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;750&quot; data-start=&quot;707&quot;&gt;\r\n	&lt;p data-end=&quot;750&quot; data-start=&quot;709&quot;&gt;Sản phẩm giao không đúng với đơn đặt hàng&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;779&quot; data-start=&quot;751&quot;&gt;\r\n	&lt;p data-end=&quot;779&quot; data-start=&quot;753&quot;&gt;Sản phẩm bị thiếu số lượng&lt;/p&gt;\r\n	&lt;/li&gt;\r\n&lt;/ul&gt;\r\n\r\n&lt;p data-end=&quot;848&quot; data-start=&quot;781&quot;&gt;⏱ &lt;strong data-end=&quot;805&quot; data-start=&quot;783&quot;&gt;Thời gian yêu cầu:&lt;/strong&gt; trong vòng &lt;strong data-end=&quot;827&quot; data-start=&quot;817&quot;&gt;24 giờ&lt;/strong&gt; kể từ khi nhận hàng.&lt;/p&gt;\r\n\r\n&lt;hr data-end=&quot;853&quot; data-start=&quot;850&quot; /&gt;\r\n&lt;h3 data-end=&quot;893&quot; data-start=&quot;855&quot;&gt;2. Điều kiện không áp dụng đổi trả&lt;/h3&gt;\r\n\r\n&lt;ul data-end=&quot;1023&quot; data-start=&quot;895&quot;&gt;\r\n	&lt;li data-end=&quot;920&quot; data-start=&quot;895&quot;&gt;\r\n	&lt;p data-end=&quot;920&quot; data-start=&quot;897&quot;&gt;Sản phẩm đã qua sử dụng&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;956&quot; data-start=&quot;921&quot;&gt;\r\n	&lt;p data-end=&quot;956&quot; data-start=&quot;923&quot;&gt;Sản phẩm bị hư hỏng do khách hàng&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;990&quot; data-start=&quot;957&quot;&gt;\r\n	&lt;p data-end=&quot;990&quot; data-start=&quot;959&quot;&gt;Sản phẩm đặt theo yêu cầu riêng&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;1023&quot; data-start=&quot;991&quot;&gt;\r\n	&lt;p data-end=&quot;1023&quot; data-start=&quot;993&quot;&gt;Quá thời gian quy định đổi trả&lt;/p&gt;\r\n	&lt;/li&gt;\r\n&lt;/ul&gt;\r\n\r\n&lt;hr data-end=&quot;1028&quot; data-start=&quot;1025&quot; /&gt;\r\n&lt;h3 data-end=&quot;1054&quot; data-start=&quot;1030&quot;&gt;3. Quy trình đổi trả&lt;/h3&gt;\r\n\r\n&lt;ol data-end=&quot;1207&quot; data-start=&quot;1056&quot;&gt;\r\n	&lt;li data-end=&quot;1091&quot; data-start=&quot;1056&quot;&gt;\r\n	&lt;p data-end=&quot;1091&quot; data-start=&quot;1059&quot;&gt;Liên hệ người bán hoặc HanMarket&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;1127&quot; data-start=&quot;1092&quot;&gt;\r\n	&lt;p data-end=&quot;1127&quot; data-start=&quot;1095&quot;&gt;Cung cấp hình ảnh/video sản phẩm&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;1159&quot; data-start=&quot;1128&quot;&gt;\r\n	&lt;p data-end=&quot;1159&quot; data-start=&quot;1131&quot;&gt;Xác nhận tình trạng hàng hóa&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;1207&quot; data-start=&quot;1160&quot;&gt;\r\n	&lt;p data-end=&quot;1207&quot; data-start=&quot;1163&quot;&gt;Thực hiện đổi hoặc hoàn tiền theo thỏa thuận&lt;/p&gt;\r\n	&lt;/li&gt;\r\n&lt;/ol&gt;\r\n\r\n&lt;hr data-end=&quot;1212&quot; data-start=&quot;1209&quot; /&gt;\r\n&lt;h3 data-end=&quot;1230&quot; data-start=&quot;1214&quot;&gt;4. Hoàn tiền&lt;/h3&gt;\r\n\r\n&lt;ul data-end=&quot;1408&quot; data-start=&quot;1232&quot;&gt;\r\n	&lt;li data-end=&quot;1297&quot; data-start=&quot;1232&quot;&gt;\r\n	&lt;p data-end=&quot;1297&quot; data-start=&quot;1234&quot;&gt;Hoàn tiền qua hình thức đã thanh toán (chuyển khoản / tiền mặt)&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;1340&quot; data-start=&quot;1298&quot;&gt;\r\n	&lt;p data-end=&quot;1340&quot; data-start=&quot;1300&quot;&gt;Thời gian xử lý: &lt;strong data-end=&quot;1340&quot; data-start=&quot;1317&quot;&gt;3 – 7 ngày làm việc&lt;/strong&gt;&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;1408&quot; data-start=&quot;1341&quot;&gt;\r\n	&lt;p data-end=&quot;1408&quot; data-start=&quot;1343&quot;&gt;Phí vận chuyển phát sinh (nếu có) sẽ được thỏa thuận giữa hai bên&lt;/p&gt;\r\n	&lt;/li&gt;\r\n&lt;/ul&gt;', 'HanMarket mong muốn mang lại trải nghiệm mua sắm tốt nhất cho khách hàng khi mua hàng lưu niệm tại Chợ Hàn Đà Nẵng.', 'HanMarket mong muốn mang lại trải nghiệm mua sắm tốt nhất cho khách hàng khi mua hàng lưu niệm tại Chợ Hàn Đà Nẵng.', 'HanMarket mong muốn mang lại trải nghiệm mua sắm tốt nhất cho khách hàng khi mua hàng lưu niệm tại Chợ Hàn Đà Nẵng.');
INSERT INTO `oc_information_description` (`information_id`, `language_id`, `title`, `description`, `meta_title`, `meta_description`, `meta_keyword`) VALUES (7, 1, 'FAQ', '&lt;p&gt;HanMarket là nền tảng quản lý bán hàng và hỗ trợ mua bán hàng lưu niệm tại Chợ Hàn Đà Nẵng.&lt;/p&gt;', 'HanMarket là nền tảng quản lý bán hàng và hỗ trợ mua bán hàng lưu niệm tại Chợ Hàn Đà Nẵng.', 'HanMarket là nền tảng quản lý bán hàng và hỗ trợ mua bán hàng lưu niệm tại Chợ Hàn Đà Nẵng.', 'HanMarket là nền tảng quản lý bán hàng và hỗ trợ mua bán hàng lưu niệm tại Chợ Hàn Đà Nẵng.');
INSERT INTO `oc_information_description` (`information_id`, `language_id`, `title`, `description`, `meta_title`, `meta_description`, `meta_keyword`) VALUES (7, 2, 'Câu hỏi thường gặp', '&lt;h2 data-end=&quot;1630&quot; data-start=&quot;1605&quot;&gt;&lt;strong data-end=&quot;1630&quot; data-start=&quot;1608&quot;&gt;CÂU HỎI THƯỜNG GẶP&lt;/strong&gt;&lt;/h2&gt;\r\n\r\n&lt;h3 data-end=&quot;1654&quot; data-start=&quot;1632&quot;&gt;❓ HanMarket là gì?&lt;/h3&gt;\r\n\r\n&lt;p data-end=&quot;1746&quot; data-start=&quot;1655&quot;&gt;HanMarket là nền tảng quản lý bán hàng và hỗ trợ mua bán hàng lưu niệm tại Chợ Hàn Đà Nẵng.&lt;/p&gt;\r\n\r\n&lt;h3 data-end=&quot;1798&quot; data-start=&quot;1748&quot;&gt;❓ Tôi có thể mua hàng trực tiếp tại chợ không?&lt;/h3&gt;\r\n\r\n&lt;p data-end=&quot;1856&quot; data-start=&quot;1799&quot;&gt;Có. Một số sản phẩm hỗ trợ nhận hàng trực tiếp tại ki-ốt.&lt;/p&gt;\r\n\r\n&lt;h3 data-end=&quot;1904&quot; data-start=&quot;1858&quot;&gt;❓ HanMarket có phải đơn vị bán hàng không?&lt;/h3&gt;\r\n\r\n&lt;p data-end=&quot;2001&quot; data-start=&quot;1905&quot;&gt;Không. HanMarket là &lt;strong data-end=&quot;1963&quot; data-start=&quot;1925&quot;&gt;nền tảng hỗ trợ quản lý và kết nối&lt;/strong&gt;, việc mua bán do các ki-ốt thực hiện.&lt;/p&gt;\r\n\r\n&lt;h3 data-end=&quot;2048&quot; data-start=&quot;2003&quot;&gt;❓ Dữ liệu bán hàng có được bảo mật không?&lt;/h3&gt;\r\n\r\n&lt;p data-end=&quot;2106&quot; data-start=&quot;2049&quot;&gt;Có. Dữ liệu được bảo mật và không chia sẻ cho bên thứ ba.&lt;/p&gt;', 'HanMarket là nền tảng quản lý bán hàng và hỗ trợ mua bán hàng lưu niệm tại Chợ Hàn Đà Nẵng.', 'HanMarket là nền tảng quản lý bán hàng và hỗ trợ mua bán hàng lưu niệm tại Chợ Hàn Đà Nẵng.', 'HanMarket là nền tảng quản lý bán hàng và hỗ trợ mua bán hàng lưu niệm tại Chợ Hàn Đà Nẵng.');
