INSERT INTO `oc_information_description` (`information_id`, `language_id`, `title`, `description`, `meta_title`, `meta_description`, `meta_keyword`) VALUES (8, 2, 'Chính sách bảo hành', '&lt;h2 data-end=&quot;2220&quot; data-start=&quot;2194&quot;&gt;&lt;strong data-end=&quot;2220&quot; data-start=&quot;2197&quot;&gt;CHÍNH SÁCH BẢO HÀNH&lt;/strong&gt;&lt;/h2&gt;\r\n\r\n&lt;ul data-end=&quot;2420&quot; data-start=&quot;2222&quot;&gt;\r\n	&lt;li data-end=&quot;2306&quot; data-start=&quot;2222&quot;&gt;\r\n	&lt;p data-end=&quot;2306&quot; data-start=&quot;2224&quot;&gt;Một số sản phẩm lưu niệm có thể được bảo hành theo chính sách riêng của từng ki-ốt&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;2371&quot; data-start=&quot;2307&quot;&gt;\r\n	&lt;p data-end=&quot;2371&quot; data-start=&quot;2309&quot;&gt;Thời gian và điều kiện bảo hành sẽ được thông báo khi mua hàng&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;2420&quot; data-start=&quot;2372&quot;&gt;\r\n	&lt;p data-end=&quot;2420&quot; data-start=&quot;2374&quot;&gt;Không bảo hành với hư hỏng do sử dụng sai cách&lt;/p&gt;\r\n	&lt;/li&gt;\r\n&lt;/ul&gt;', 'CHÍNH SÁCH BẢO HÀNH', 'CHÍNH SÁCH BẢO HÀNH', 'CHÍNH SÁCH BẢO HÀNH');
