INSERT INTO `oc_information_description` (`information_id`, `language_id`, `title`, `description`, `meta_title`, `meta_description`, `meta_keyword`) VALUES (10, 1, 'Legal Notice', '&lt;h2 data-end=&quot;2758&quot; data-start=&quot;2734&quot;&gt;&lt;strong data-end=&quot;2758&quot; data-start=&quot;2737&quot;&gt;HÔNG BÁO PHÁP LÝ&lt;/strong&gt;&lt;/h2&gt;\r\n\r\n&lt;p data-end=&quot;2945&quot; data-start=&quot;2760&quot;&gt;HanMarket là nền tảng hỗ trợ quản lý bán hàng, &lt;strong data-end=&quot;2855&quot; data-start=&quot;2807&quot;&gt;không đại diện pháp lý cho các hộ kinh doanh&lt;/strong&gt;.&lt;br data-end=&quot;2859&quot; data-start=&quot;2856&quot; /&gt;\r\nMọi hoạt động mua bán, thuế và hóa đơn thuộc trách nhiệm của từng ki-ốt/hộ kinh doanh.&lt;/p&gt;\r\n\r\n&lt;h2 data-end=&quot;3157&quot; data-start=&quot;3121&quot;&gt;&lt;strong data-end=&quot;3157&quot; data-start=&quot;3124&quot;&gt;TUYÊN BỐ MIỄN TRỪ TRÁCH NHIỆM&lt;/strong&gt;&lt;/h2&gt;\r\n\r\n&lt;ul data-end=&quot;3336&quot; data-start=&quot;3159&quot;&gt;\r\n	&lt;li data-end=&quot;3206&quot; data-start=&quot;3159&quot;&gt;\r\n	&lt;p data-end=&quot;3206&quot; data-start=&quot;3161&quot;&gt;HanMarket không đại diện cho cơ quan nhà nước&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;3270&quot; data-start=&quot;3207&quot;&gt;\r\n	&lt;p data-end=&quot;3270&quot; data-start=&quot;3209&quot;&gt;Không chịu trách nhiệm pháp lý cho dữ liệu do người dùng nhập&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;3336&quot; data-start=&quot;3271&quot;&gt;\r\n	&lt;p data-end=&quot;3336&quot; data-start=&quot;3273&quot;&gt;Mọi giao dịch mua bán là thỏa thuận giữa người mua và người bán&lt;/p&gt;\r\n	&lt;/li&gt;\r\n&lt;/ul&gt;', 'TUYÊN BỐ MIỄN TRỪ TRÁCH NHIỆM', 'TUYÊN BỐ MIỄN TRỪ TRÁCH NHIỆM', 'TUYÊN BỐ MIỄN TRỪ TRÁCH NHIỆM');
INSERT INTO `oc_information_description` (`information_id`, `language_id`, `title`, `description`, `meta_title`, `meta_description`, `meta_keyword`) VALUES (10, 2, 'Thông tin pháp lý', '&lt;h2 data-end=&quot;2758&quot; data-start=&quot;2734&quot;&gt;&lt;strong data-end=&quot;2758&quot; data-start=&quot;2737&quot;&gt;HÔNG BÁO PHÁP LÝ&lt;/strong&gt;&lt;/h2&gt;\r\n\r\n&lt;p data-end=&quot;2945&quot; data-start=&quot;2760&quot;&gt;HanMarket là nền tảng hỗ trợ quản lý bán hàng, &lt;strong data-end=&quot;2855&quot; data-start=&quot;2807&quot;&gt;không đại diện pháp lý cho các hộ kinh doanh&lt;/strong&gt;.&lt;br data-end=&quot;2859&quot; data-start=&quot;2856&quot; /&gt;\r\nMọi hoạt động mua bán, thuế và hóa đơn thuộc trách nhiệm của từng ki-ốt/hộ kinh doanh.&lt;/p&gt;\r\n\r\n&lt;h2 data-end=&quot;3157&quot; data-start=&quot;3121&quot;&gt;&lt;strong data-end=&quot;3157&quot; data-start=&quot;3124&quot;&gt;TUYÊN BỐ MIỄN TRỪ TRÁCH NHIỆM&lt;/strong&gt;&lt;/h2&gt;\r\n\r\n&lt;ul data-end=&quot;3336&quot; data-start=&quot;3159&quot;&gt;\r\n	&lt;li data-end=&quot;3206&quot; data-start=&quot;3159&quot;&gt;\r\n	&lt;p data-end=&quot;3206&quot; data-start=&quot;3161&quot;&gt;HanMarket không đại diện cho cơ quan nhà nước&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;3270&quot; data-start=&quot;3207&quot;&gt;\r\n	&lt;p data-end=&quot;3270&quot; data-start=&quot;3209&quot;&gt;Không chịu trách nhiệm pháp lý cho dữ liệu do người dùng nhập&lt;/p&gt;\r\n	&lt;/li&gt;\r\n	&lt;li data-end=&quot;3336&quot; data-start=&quot;3271&quot;&gt;\r\n	&lt;p data-end=&quot;3336&quot; data-start=&quot;3273&quot;&gt;Mọi giao dịch mua bán là thỏa thuận giữa người mua và người bán&lt;/p&gt;\r\n	&lt;/li&gt;\r\n&lt;/ul&gt;', 'THÔNG BÁO PHÁP LÝ - TUYÊN BỐ MIỄN TRỪ TRÁCH NHIỆM', 'THÔNG BÁO PHÁP LÝ - TUYÊN BỐ MIỄN TRỪ TRÁCH NHIỆM', 'THÔNG BÁO PHÁP LÝ - TUYÊN BỐ MIỄN TRỪ TRÁCH NHIỆM');
